<script setup lang="ts">
definePageMeta({layout:'workspace'})
type Member={user_id:string;role:string;profiles:{display_name:string|null}|null}
type Request={id:string;user_id:string;email:string;given_name:string;family_name:string;status:string;created_at:string}
type Invitation={id:string;email:string;expires_at:string;accepted_at:string|null;revoked_at:string|null;created_at:string}
const db=useSupabaseClient(),{schoolId,schoolRole,platformAdmin}=useSchool()
const canManage=computed(()=>platformAdmin.value||schoolRole.value==='school_admin')
const members=ref<Member[]>([]),requests=ref<Request[]>([]),invitations=ref<Invitation[]>([])
const loading=ref(false),error=ref(''),search=ref(''),filter=ref('all'),selected=ref<Member|null>(null),open=ref(false)
const filtered=computed(()=>members.value.filter(m=>(filter.value==='all'||m.role===filter.value)&&(m.profiles?.display_name||m.user_id).toLowerCase().includes(search.value.trim().toLowerCase())))
const admins=computed(()=>members.value.filter(m=>m.role==='school_admin').length)
const teachers=computed(()=>members.value.filter(m=>m.role==='teacher').length)
const pending=computed(()=>requests.value.filter(r=>r.status==='pending').length)
const inviteStatus=(i:Invitation)=>i.revoked_at?'Revoked':i.accepted_at?'Accepted':new Date(i.expires_at).getTime()<Date.now()?'Expired':'Pending'
async function load(){if(!schoolId.value){members.value=[];requests.value=[];invitations.value=[];return}loading.value=true;error.value='';try{
const m=await db.from('school_memberships').select('user_id,role').eq('school_id',schoolId.value)
if(m.error)throw m.error;const raw=(m.data||[]) as {user_id:string;role:string}[];const ids=raw.map(x=>x.user_id);const p=ids.length?await db.from('profiles').select('id,display_name').in('id',ids):{data:[],error:null};if(p.error)throw p.error;const names=new Map((p.data||[]).map(x=>[x.id,x.display_name]));members.value=raw.map(x=>({...x,profiles:{display_name:names.get(x.user_id)||null}}))
if(canManage.value){const [r,i]=await Promise.all([db.from('school_staff_requests').select('id,user_id,email,given_name,family_name,status,created_at').eq('school_id',schoolId.value).order('created_at',{ascending:false}),db.from('school_staff_invitations').select('id,email,expires_at,accepted_at,revoked_at,created_at').eq('school_id',schoolId.value).order('created_at',{ascending:false})]);if(r.error||i.error)throw r.error||i.error;requests.value=(r.data||[]) as Request[];invitations.value=(i.data||[]) as Invitation[]}else{requests.value=[];invitations.value=[]}
}catch(e:any){error.value=e.message||'Unable to load staff'}finally{loading.value=false}}
watch([schoolId,canManage],()=>{open.value=false;void load()},{immediate:true})
</script>
<template><div class="space-y-6">
<div class="flex flex-wrap items-stretch justify-end gap-2"><div v-for="m in [{label:'Total staff',value:members.length},{label:'Administrators',value:admins},{label:'Teachers',value:teachers},{label:'Pending requests',value:pending}]" :key="m.label" class="flex min-w-[125px] flex-1 items-center justify-between gap-3 rounded-xl border border-[var(--border)] bg-[var(--panel)] px-4 py-3 sm:max-w-[200px]"><span class="text-xs text-[var(--muted)]">{{m.label}}</span><strong class="text-xl">{{m.value}}</strong></div></div>
<p v-if="error" role="alert" class="rounded-xl bg-red-50 p-4 text-red-700">{{error}}</p>
<UiPanel><div class="mb-5 flex flex-wrap items-center justify-between gap-3"><h2 class="text-lg font-bold">Staff directory</h2><button class="rounded-xl border border-[var(--border)] px-4 py-2 text-sm" :disabled="loading" @click="load">Refresh</button></div><div class="mb-5 flex flex-wrap gap-3"><input v-model="search" aria-label="Search staff" placeholder="Search staff" class="min-w-[200px] flex-1 rounded-lg border border-[var(--border)] bg-[var(--surface)] p-3"/><select v-model="filter" aria-label="Filter staff role" class="rounded-lg border border-[var(--border)] bg-[var(--surface)] p-3"><option value="all">All roles</option><option value="school_admin">School administrators</option><option value="teacher">Teachers</option></select></div><p v-if="loading" class="py-6">Loading staff…</p><div v-else class="overflow-x-auto"><table class="w-full min-w-[430px] text-left text-sm"><thead><tr class="border-b border-[var(--border)] text-[var(--muted)]"><th class="py-3">Staff member</th><th class="p-3">Role</th><th class="p-3">Action</th></tr></thead><tbody><tr v-for="m in filtered" :key="m.user_id" class="border-b border-[var(--border)]"><td class="py-4 font-semibold">{{m.profiles?.display_name||'Name not provided'}}</td><td class="p-3">{{m.role==='school_admin'?'School administrator':m.role==='teacher'?'Teacher':m.role}}</td><td class="p-3"><button type="button" :aria-label="'View '+(m.profiles?.display_name||'staff member')" class="rounded-lg border border-[var(--border)] p-2 text-blue-600" @click="selected=m;open=true"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="2" width="18" height="20" rx="2"/><circle cx="12" cy="10" r="3"/><path d="M7 18a5 5 0 0 1 10 0"/></svg></button></td></tr></tbody></table><p v-if="!filtered.length" class="py-8 text-center text-[var(--muted)]">No matching staff.</p></div></UiPanel>
<UiPanel v-if="canManage"><h2 class="mb-3 text-lg font-bold">Staff access requests</h2><p class="mb-4 text-sm text-[var(--muted)]">Existing requests are shown here for review. Approval controls will be added after the access workflow is verified.</p><UiHoverScrollbar max-height="18rem"><div v-for="r in requests" :key="r.id" class="flex flex-wrap items-center justify-between gap-2 border-b border-[var(--border)] py-3 text-sm"><div><strong>{{r.given_name}} {{r.family_name}}</strong><p class="text-[var(--muted)]">{{r.email}}</p></div><span class="rounded-lg bg-[var(--surface)] px-3 py-1">{{r.status}}</span></div><p v-if="!requests.length" class="py-4 text-sm text-[var(--muted)]">No staff access requests.</p></UiHoverScrollbar></UiPanel>
<UiPanel v-if="canManage"><h2 class="mb-3 text-lg font-bold">Staff invitations</h2><p class="mb-4 text-sm text-[var(--muted)]">Invitation status only. Sending and revoking invitations will be enabled after the secure invitation workflow is verified.</p><UiHoverScrollbar max-height="18rem"><div v-for="i in invitations" :key="i.id" class="flex flex-wrap items-center justify-between gap-2 border-b border-[var(--border)] py-3 text-sm"><span>{{i.email}}</span><span class="rounded-lg bg-[var(--surface)] px-3 py-1">{{inviteStatus(i)}}</span></div><p v-if="!invitations.length" class="py-4 text-sm text-[var(--muted)]">No staff invitations.</p></UiHoverScrollbar></UiPanel>
<div v-if="open&&selected" class="fixed inset-0 z-50 grid place-items-center bg-black/60 p-4" @click.self="open=false"><section role="dialog" aria-modal="true" aria-label="Staff details" class="w-full max-w-lg rounded-2xl bg-[var(--surface)] p-6 text-[var(--ink)] shadow-xl"><header class="mb-5 flex items-center justify-between"><h2 class="text-xl font-bold">Staff details</h2><button aria-label="Close" @click="open=false">✕</button></header><div class="space-y-3"><div class="rounded-xl bg-[var(--panel)] p-4"><p class="text-xs text-[var(--muted)]">Name</p><strong>{{selected.profiles?.display_name||'Name not provided'}}</strong></div><div class="rounded-xl bg-[var(--panel)] p-4"><p class="text-xs text-[var(--muted)]">School role</p><strong>{{selected.role==='school_admin'?'School administrator':selected.role==='teacher'?'Teacher':selected.role}}</strong></div></div><div class="mt-5 flex justify-end"><button class="rounded-xl border border-[var(--border)] px-5 py-3" @click="open=false">Close</button></div></section></div>
</div></template>